import csv
from dataclasses import dataclass


@dataclass
class Trip:
    rider: str
    km: float
    minutes: int
    surge: float = 1.0


class FareTable:
    BASE = 2.5
    PER_KM = 1.1
    PER_MIN = 0.3

    def __init__(self):
        self.trips = []

    def load(self, path):
        with open(path) as f:
            for row in csv.DictReader(f):
                self.trips.append(Trip(row['rider'], float(row['km']), int(row['minutes']), float(row.get('surge', 1))))

    def fare(self, t):
        return (self.BASE + t.km * self.PER_KM + t.minutes * self.PER_MIN) * t.surge

    def by_rider(self):
        out = {}
        for t in self.trips:
            out[t.rider] = out.get(t.rider, 0) + self.fare(t)
        return out

    def top(self, n):
        return sorted(self.by_rider().items(), key=lambda kv: kv[1])[:n]
